def solve_n_queens(n):
    cols = set()
    pos_diag = set()
    neg_diag = set()
    solution = [-1]*n
    def backtrack(row):
        if row==n:
            return True
        for col in range(n):
            if col in cols or (row+col) in pos_diag or (row-col) in neg_diag:
                continue
            cols.add(col); pos_diag.add(row+col); neg_diag.add(row-col)
            solution[row]=col
            if backtrack(row+1):
                return True
            cols.remove(col); pos_diag.remove(row+col); neg_diag.remove(row-col)
        return False
    if backtrack(0):
        return solution
    return None

